local m=script.Parent local base=m:GetPivot()*CFrame.Angles(0,0,math.rad(35)) local sp=m.Blade.Tip.Sparks local function pose(d) m:PivotTo(base*CFrame.Angles(0,math.rad(d),0)) end while true do for i=0,1,1/20 do pose(-60*i) task.wait() end for i=0,1,1/6 do pose(-60+200*(1-(1-i)^3)) task.wait() end sp:Emit(30) task.wait(0.5) for i=0,1,1/30 do pose(140-140*i) task.wait() end task.wait(0.6) end